def transform(grid):
    out = [row[:] for row in grid]
    rows = [r for r in range(len(grid)) if 3 in grid[r]]
    cols = [c for c in range(len(grid[0])) if any(grid[r][c] == 3 for r in range(len(grid)))]

    top, bottom = min(rows), max(rows)
    left, right = min(cols), max(cols)

    seed = next(
        (r, c)
        for r in range(top + 1, bottom)
        for c in range(left + 1, right)
        if grid[r][c] == 3
    )

    for r in range(top + 1, bottom):
        for c in range(left + 1, right):
            if (r, c) == seed:
                continue
            out[r][c] = 4
            distance = max(abs(r - seed[0]), abs(c - seed[1]))
            if distance > 0 and distance % 2 == 0:
                out[r][c] = 2

    return out
